import React, { useState } from 'react';
import AQIInputForm from '../components/AQIInputForm';
import PredictionResult from '../components/PredictionResult';
import WeatherCard from '../components/WeatherCard';
import BackgroundMap from '../components/BackgroundMap';
import '../styles/dashboard.css';

const Dashboard = () => {
  const [result, setResult] = useState(null);
  const [features, setFeatures] = useState({
    PM2_5: 47,
    CO: 10,
    NO2: 20,
    NH3: 30,
    O3: 60,
    Temp: 38,
    Humidity: 54,
    Pressure: 1013
  });

  return (
    <div className="dashboard-container">
      <h1>🌫️ Live Air Quality Index - Dubai</h1>

      <div className="dashboard-grid">
        <div>
          <AQIInputForm features={features} setFeatures={setFeatures} setResult={setResult} />
          <PredictionResult result={result} />
        </div>

        <div>
          <WeatherCard temp={features.Temp} humidity={features.Humidity} />
          <BackgroundMap />
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
